create table if not exists machines (id text primary key, name text not null, slug text unique not null, description text, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists products (id text primary key, machine_id text references machines(id), title text not null, slug text unique not null, description text, tier text not null, price_aud integer not null, stripe_price_id text, access_type text not null, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists content_items (id text primary key, title text not null, slug text unique not null, description text, content_type text not null, access_type text not null, status text not null default 'draft', file_path text, preview_image_path text, tags text[] not null default '{}', assigned_machine_id text references machines(id), assigned_product_id text references products(id), assigned_subscription_tier text, release_date timestamptz, expiry_date timestamptz, created_by text, approved_by text, internal_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists content_drops (id text primary key, drop_title text not null, drop_slug text unique not null, drop_description text, drop_type text not null, scheduled_date timestamptz, published_at timestamptz, status text not null default 'draft', assigned_machine_id text references machines(id), assigned_product_id text references products(id), eligible_subscription_tier text, email_notification_sent boolean not null default false, publish_notes text, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists content_drop_items (id text primary key, content_drop_id text not null references content_drops(id), content_item_id text not null references content_items(id), sort_order integer not null default 0, created_at timestamptz not null default now(), unique(content_drop_id, content_item_id));
create table if not exists customer_entitlements (id text primary key, user_id text, product_id text references products(id), machine_id text references machines(id), stripe_customer_id text, stripe_subscription_id text, access_type text not null, status text not null default 'active', starts_at timestamptz not null default now(), expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists download_logs (id text primary key, user_id text, content_item_id text not null references content_items(id), product_id text references products(id), machine_id text, access_type text not null, download_status text not null, downloaded_at timestamptz not null default now());
create table if not exists content_bundles (id text primary key, bundle_title text not null, bundle_slug text unique not null, bundle_description text, cover_image_path text, price integer not null, stripe_price_id text, assigned_machine_id text references machines(id), access_rules jsonb, upsell_product_id text references products(id), order_bump_product_id text references products(id), status text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists bundle_items (id text primary key, bundle_id text not null references content_bundles(id), content_item_id text not null references content_items(id), sort_order integer not null default 0, created_at timestamptz not null default now(), unique(bundle_id, content_item_id));
create table if not exists email_logs (id text primary key, user_id text, email_type text not null, related_content_id text references content_items(id), related_drop_id text references content_drops(id), sent_to text not null, status text not null, sent_at timestamptz, error_message text);
create table if not exists content_analytics (id text primary key, content_item_id text references content_items(id), machine_id text references machines(id), product_id text references products(id), views integer not null default 0, downloads integer not null default 0, purchases_influenced integer not null default 0, revenue_attributed integer not null default 0, subscriber_unlocks integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table machines enable row level security;
alter table products enable row level security;
alter table content_items enable row level security;
alter table content_drops enable row level security;
alter table customer_entitlements enable row level security;
alter table download_logs enable row level security;
alter table content_bundles enable row level security;
